_🗄️ Data Integrity & Integration_ | _🟠 Major_ | _⚡ Quick win_

**Report partial results when a bulk delete fails midway.**

The loop deletes each purchase in sequence. If one request fails, `handleToolError` returns a generic error, and the already-deleted purchase IDs are lost. The caller cannot determine the remaining work.

Track the deleted IDs and include them in the failure path.





<details>
<summary>🐛 Proposed fix to report deleted and failed IDs</summary>

```diff
       case "quickfile_purchase_delete": {
         const purchaseIds = args.purchaseIds as number[];
+        const deleted: number[] = [];
         for (const purchaseId of purchaseIds) {
-          await client.request(`/purchases/${purchaseId}`, {
-            method: "DELETE",
-            body: {
-              delete_associated_payments:
-                args.deleteAssociatedPayments ?? true,
-            },
-          });
+          try {
+            await client.request(`/purchases/${purchaseId}`, {
+              method: "DELETE",
+              body: {
+                delete_associated_payments:
+                  args.deleteAssociatedPayments ?? true,
+              },
+            });
+            deleted.push(purchaseId);
+          } catch (error) {
+            return errorResult(
+              `Deleted ${JSON.stringify(deleted)} before failing on purchase ${purchaseId}: ` +
+                `${error instanceof Error ? error.message : String(error)}`,
+            );
+          }
         }
         return successResult({
           success: true,
           purchaseIds,
-          purchasesDeleted: purchaseIds.length,
+          purchasesDeleted: deleted.length,
         });
       }
